#:property InvariantGlobalization=false

// Find the earliest Friday the 13th in the proleptic Gregorian calendar
// and count total Friday the 13ths in a full 400-year cycle.

// Earliest Friday the 13th starting from 0001-01-01
var date = new DateTime(1, 1, 13);
while (date.DayOfWeek != DayOfWeek.Friday)
    date = date.AddMonths(1);

Console.WriteLine($"Earliest Friday the 13th: {date:yyyy-MM-dd} ({date.DayOfWeek})");

// Count Friday the 13ths in a full 400-year cycle (the Gregorian calendar repeats every 400 years)
int count = 0;
var start = new DateTime(1, 1, 13);
var end = new DateTime(401, 1, 1);

while (start < end)
{
    if (start.DayOfWeek == DayOfWeek.Friday)
        count++;
    start = start.AddMonths(1);
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");

// Bonus: breakdown by day-of-week for the 13th
Console.WriteLine("\n--- 13th-of-month distribution over 400 years ---");
var tally = new int[7];
var d = new DateTime(1, 1, 13);
while (d < end)
{
    tally[(int)d.DayOfWeek]++;
    d = d.AddMonths(1);
}

foreach (DayOfWeek dow in Enum.GetValues<DayOfWeek>())
    Console.WriteLine($"  {dow,-10} {tally[(int)dow],4}");

